    h, w = len(grid), len(grid[0])
    # The task's outlined shapes have a one-cell border; replace enclosed background with 7.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 8:
                continue
            # Locate the bounding box of this object's color.
            cells = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == color]
            r0, r1 = min(i for i, j in cells), max(i for i, j in cells)
            c0, c1 = min(j for i, j in cells), max(j for i, j in cells)
            # Skip if this cell's color object doesn't form a rectangular outline.
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            if (r, c) != (r0, c0):
                continue
            for i in range(r0+1, r1):
                for j in range(c0+1, c1):
                    if grid[i][j] == 8:
                        out[i][j] = 7
    return out
